   title=tab==='tinta'?'Inventario de tintas por proveedor':'Inventario de herramentales por proveedor';
   if(typeFilter)notes.push('Tipo: '+typeFilter);if(providerFilter)notes.push('Proveedor: '+providerFilter);if(statusFilter)notes.push('Estado: '+(statusFilter==='negative'?'Saldo negativo':statusFilter));
