   const products=data.products.filter(p=>p.category===catalogTab&&`${p.name} ${p.code} ${p.provider}`.toLowerCase().includes(query.toLowerCase()));
   columns=[col('Proveedor',105),col('Producto',165),col('Código',95),col('Tipo',65),col('Vida útil (días)',65),col('Recompra (g / pzas)',90),col('Máximo (g / pzas)',90),col('Costo kg / pza MXN',103)];
   rows=products.map(p=>[p.provider,p.name,p.code,p.kind,p.shelf_days??365,num(p.minimum),num(p.maximum||0),money(p.cost_kg||0)]);summary=products.length+' productos. Las cantidades de catálogo no representan existencias.';
