   rows=incidents.map(i=>[i.folio,displayDate(i.date),i.order_ref+(i.np?' / '+i.np:''),i.machine,i.description,i.responsible,i.action||'-',i.impact,i.status]);
   summary=incidents.length+' incidencias · Los reportes individuales incluyen la evidencia y la validación.';
