   rows=preparations.map(p=>[displayDate(p.date),p.folio,p.np,p.start_time,p.end_time+(p.end_next_day?' (+1 día)':''),num(p.minutes),p.requested_date?displayDate(p.requested_date):'-',p.requested_time||'-',p.supplies,p.product,p.notes||'-']);
   summary=preparations.length+' preparaciones · Tiempo total: '+num(preparations.reduce((s,p)=>s+Number(p.minutes),0))+' min';
