   const detail=filteredProductionRows();
   columns=[col('Orden',82),col('NP',55),col('Fecha',55),col('Prensista',55),col('Tinta / código',93),col('Lote',58),col('Ingreso (g)',52),col('Egreso (g)',52),col('Gramos totales',55),col('Metros',45),col('Notas',65),col('Producto',66),col('Estado',45)];
